      recov_err_code.add_hdl_path_slice(
          "u_reg.u_recov_err_code_usb_timeout_err.q",
          10, 1, 0, "BkdrRegPathRtl");

      fatal_err_code =
          (clkmgr_reg_fatal_err_code::
           type_id::create("fatal_err_code"));
      fatal_err_code.configure(.blk_parent(this));
      fatal_err_code.build(csr_excl);
      default_map.add_reg(.rg(fatal_err_code),
                          .offset(32'h54));
      fatal_err_code.add_hdl_path_slice(
          "u_reg.u_fatal_err_code_reg_intg.q",
          0, 1, 0, "BkdrRegPathRtl");
      fatal_err_code.add_hdl_path_slice(
          "u_reg.u_fatal_err_code_idle_cnt.q",
          1, 1, 0, "BkdrRegPathRtl");
      fatal_err_code.add_hdl_path_slice(
          "u_reg.u_fatal_err_code_shadow_storage_err.q",
          2, 1, 0, "BkdrRegPathRtl");

      // assign locked reg to its regwen reg
      extclk_ctrl_regwen.add_lockable_reg_or_fld(extclk_ctrl);
      jitter_regwen.add_lockable_reg_or_fld(jitter_enable);
      measure_ctrl_regwen.add_lockable_reg_or_fld(io_meas_ctrl_en);
      measure_ctrl_regwen.add_lockable_reg_or_fld(io_meas_ctrl_shadowed);
      measure_ctrl_regwen.add_lockable_reg_or_fld(io_div2_meas_ctrl_en);
      measure_ctrl_regwen.add_lockable_reg_or_fld(io_div2_meas_ctrl_shadowed);
      measure_ctrl_regwen.add_lockable_reg_or_fld(io_div4_meas_ctrl_en);
      measure_ctrl_regwen.add_lockable_reg_or_fld(io_div4_meas_ctrl_shadowed);
      measure_ctrl_regwen.add_lockable_reg_or_fld(main_meas_ctrl_en);
      measure_ctrl_regwen.add_lockable_reg_or_fld(main_meas_ctrl_shadowed);
      measure_ctrl_regwen.add_lockable_reg_or_fld(usb_meas_ctrl_en);
      measure_ctrl_regwen.add_lockable_reg_or_fld(usb_meas_ctrl_shadowed);


      // Create functional coverage for comportable IP-specific specialized registers.
      // This function can only be called if it is a root block to get the correct gating condition
      // and avoid creating duplicated cov.
      if (this.get_parent() == null && en_dv_reg_cov) create_cov();
    endfunction : build
  endclass : clkmgr_reg_block

endpackage

