          6, 1, 0, "BkdrRegPathRtl");

      // assign locked reg to its regwen reg
      cfg_regwen.add_lockable_reg_or_fld(start);
      cfg_regwen.add_lockable_reg_or_fld(control_shadowed);
      cfg_regwen.add_lockable_reg_or_fld(sideload_clear);
