          "u_reg.u_prefix_9.q",
          0, 32, 0, "BkdrRegPathRtl");

      prefix[10] =
          (kmac_reg_prefix::
           type_id::create("prefix_10"));
      prefix[10].configure(.blk_parent(this));
      prefix[10].build(csr_excl);
      default_map.add_reg(.rg(prefix[10]),
                          .offset(32'hdc));
      prefix[10].add_hdl_path_slice(
          "u_reg.u_prefix_10.q",
