      csr_excl.add_excl(secret1_digest[0].get_full_name(),
                        CsrExclCheck, CsrAllTests);
      secret1_digest[1] =
          (otp_ctrl_core_reg_secret1_digest::
           type_id::create("secret1_digest_1"));
      secret1_digest[1].configure(.blk_parent(this));
      secret1_digest[1].build(csr_excl);
      default_map.add_reg(.rg(secret1_digest[1]),
                          .offset(32'hd8));
      secret1_digest[1].add_hdl_path_slice(
          "u_reg_core.u_secret1_digest_1.qs",
          0, 32, 0, "BkdrRegPathRtl");

      // create register tags
      csr_excl.add_excl(secret1_digest[1].get_full_name(),
                        CsrExclCheck, CsrAllTests);
      secret2_digest[0] =
          (otp_ctrl_core_reg_secret2_digest::
           type_id::create("secret2_digest_0"));
      secret2_digest[0].configure(.blk_parent(this));
      secret2_digest[0].build(csr_excl);
      default_map.add_reg(.rg(secret2_digest[0]),
                          .offset(32'hdc));
      secret2_digest[0].add_hdl_path_slice(
          "u_reg_core.u_secret2_digest_0.qs",
          0, 32, 0, "BkdrRegPathRtl");

      // create register tags
      csr_excl.add_excl(secret2_digest[0].get_full_name(),
                        CsrExclCheck, CsrAllTests);
      secret2_digest[1] =
          (otp_ctrl_core_reg_secret2_digest::
           type_id::create("secret2_digest_1"));
      secret2_digest[1].configure(.blk_parent(this));
      secret2_digest[1].build(csr_excl);
      default_map.add_reg(.rg(secret2_digest[1]),
                          .offset(32'he0));
      secret2_digest[1].add_hdl_path_slice(
          "u_reg_core.u_secret2_digest_1.qs",
          0, 32, 0, "BkdrRegPathRtl");

      // create register tags
      csr_excl.add_excl(secret2_digest[1].get_full_name(),
                        CsrExclCheck, CsrAllTests);
      // assign locked reg to its regwen reg
      direct_access_regwen.add_lockable_reg_or_fld(direct_access_cmd);
      direct_access_regwen.add_lockable_reg_or_fld(direct_access_address);
      direct_access_regwen.add_lockable_reg_or_fld(direct_access_wdata[0]);
      direct_access_regwen.add_lockable_reg_or_fld(direct_access_wdata[1]);
      check_trigger_regwen.add_lockable_reg_or_fld(check_trigger);
      check_regwen.add_lockable_reg_or_fld(check_timeout);
      check_regwen.add_lockable_reg_or_fld(integrity_check_period);
      check_regwen.add_lockable_reg_or_fld(consistency_check_period);
      direct_access_regwen.add_lockable_reg_or_fld(vendor_test_read_lock);
      direct_access_regwen.add_lockable_reg_or_fld(creator_sw_cfg_read_lock);
      direct_access_regwen.add_lockable_reg_or_fld(owner_sw_cfg_read_lock);
      direct_access_regwen.add_lockable_reg_or_fld(rot_creator_auth_codesign_read_lock);
      direct_access_regwen.add_lockable_reg_or_fld(rot_creator_auth_state_read_lock);

      // create memories
      sw_cfg_window =
          otp_ctrl_core_mem_sw_cfg_window::type_id::create("sw_cfg_window");
      sw_cfg_window.configure(.parent(this));
      default_map.add_mem(.mem(sw_cfg_window),
                          .offset(32'h800),
                          .rights("RO"));


      // Create functional coverage for comportable IP-specific specialized registers.
      // This function can only be called if it is a root block to get the correct gating condition
      // and avoid creating duplicated cov.
      if (this.get_parent() == null && en_dv_reg_cov) create_cov();
    endfunction : build
  endclass : otp_ctrl_core_reg_block

endpackage

