      regwen.add_lockable_reg_or_fld(duty_cycle[3]);
      regwen.add_lockable_reg_or_fld(duty_cycle[4]);
      regwen.add_lockable_reg_or_fld(duty_cycle[5]);
      regwen.add_lockable_reg_or_fld(blink_param[0]);
      regwen.add_lockable_reg_or_fld(blink_param[1]);
      regwen.add_lockable_reg_or_fld(blink_param[2]);
      regwen.add_lockable_reg_or_fld(blink_param[3]);
      regwen.add_lockable_reg_or_fld(blink_param[4]);
      regwen.add_lockable_reg_or_fld(blink_param[5]);


      // Create functional coverage for comportable IP-specific specialized registers.
      // This function can only be called if it is a root block to get the correct gating condition
      // and avoid creating duplicated cov.
      if (this.get_parent() == null && en_dv_reg_cov) create_cov();
    endfunction : build
  endclass : pwm_reg_block

endpackage

