           type_id::create("sw_rst_ctrl_n_5"));
      sw_rst_ctrl_n[5].configure(.blk_parent(this));
      sw_rst_ctrl_n[5].build(csr_excl);
      default_map.add_reg(.rg(sw_rst_ctrl_n[5]),
                          .offset(32'h60));
      sw_rst_ctrl_n[5].add_hdl_path_slice(
          "u_reg.u_sw_rst_ctrl_n_5.q",
          0, 1, 0, "BkdrRegPathRtl");

      // create register tags
      csr_excl.add_excl(sw_rst_ctrl_n[5].get_full_name(),
                        CsrExclWrite, CsrAllTests);
      sw_rst_ctrl_n[6] =
          (rstmgr_reg_sw_rst_ctrl_n::
           type_id::create("sw_rst_ctrl_n_6"));
      sw_rst_ctrl_n[6].configure(.blk_parent(this));
      sw_rst_ctrl_n[6].build(csr_excl);
      default_map.add_reg(.rg(sw_rst_ctrl_n[6]),
                          .offset(32'h64));
      sw_rst_ctrl_n[6].add_hdl_path_slice(
          "u_reg.u_sw_rst_ctrl_n_6.q",
          0, 1, 0, "BkdrRegPathRtl");

      // create register tags
      csr_excl.add_excl(sw_rst_ctrl_n[6].get_full_name(),
                        CsrExclWrite, CsrAllTests);
      sw_rst_ctrl_n[7] =
          (rstmgr_reg_sw_rst_ctrl_n::
           type_id::create("sw_rst_ctrl_n_7"));
      sw_rst_ctrl_n[7].configure(.blk_parent(this));
      sw_rst_ctrl_n[7].build(csr_excl);
      default_map.add_reg(.rg(sw_rst_ctrl_n[7]),
                          .offset(32'h68));
      sw_rst_ctrl_n[7].add_hdl_path_slice(
          "u_reg.u_sw_rst_ctrl_n_7.q",
          0, 1, 0, "BkdrRegPathRtl");

      // create register tags
      csr_excl.add_excl(sw_rst_ctrl_n[7].get_full_name(),
                        CsrExclWrite, CsrAllTests);
      err_code =
          (rstmgr_reg_err_code::
           type_id::create("err_code"));
      err_code.configure(.blk_parent(this));
      err_code.build(csr_excl);
      default_map.add_reg(.rg(err_code),
                          .offset(32'h6c));
      err_code.add_hdl_path_slice(
          "u_reg.u_err_code_reg_intg_err.q",
          0, 1, 0, "BkdrRegPathRtl");
      err_code.add_hdl_path_slice(
          "u_reg.u_err_code_reset_consistency_err.q",
          1, 1, 0, "BkdrRegPathRtl");
      err_code.add_hdl_path_slice(
          "u_reg.u_err_code_fsm_err.q",
          2, 1, 0, "BkdrRegPathRtl");

      // assign locked reg to its regwen reg
      alert_regwen.add_lockable_reg_or_fld(alert_info_ctrl);
      cpu_regwen.add_lockable_reg_or_fld(cpu_info_ctrl);
      sw_rst_regwen[0].add_lockable_reg_or_fld(sw_rst_ctrl_n[0]);
      sw_rst_regwen[1].add_lockable_reg_or_fld(sw_rst_ctrl_n[1]);
      sw_rst_regwen[2].add_lockable_reg_or_fld(sw_rst_ctrl_n[2]);
      sw_rst_regwen[3].add_lockable_reg_or_fld(sw_rst_ctrl_n[3]);
      sw_rst_regwen[4].add_lockable_reg_or_fld(sw_rst_ctrl_n[4]);
      sw_rst_regwen[5].add_lockable_reg_or_fld(sw_rst_ctrl_n[5]);
      sw_rst_regwen[6].add_lockable_reg_or_fld(sw_rst_ctrl_n[6]);
      sw_rst_regwen[7].add_lockable_reg_or_fld(sw_rst_ctrl_n[7]);


      // Create functional coverage for comportable IP-specific specialized registers.
      // This function can only be called if it is a root block to get the correct gating condition
      // and avoid creating duplicated cov.
      if (this.get_parent() == null && en_dv_reg_cov) create_cov();
    endfunction : build
  endclass : rstmgr_reg_block

endpackage

