    virtual function void build(uvm_reg_addr_t base_addr,
                                csr_excl_item csr_excl = null);
      // create default map
      this.default_map = create_map(.name("default_map"),
                                    .base_addr(base_addr),
                                    .n_bytes(4),
                                    .endian(UVM_LITTLE_ENDIAN));
      if (csr_excl == null) begin
        csr_excl = csr_excl_item::type_id::create("csr_excl");
        this.csr_excl = csr_excl;
      end

      // create sub blocks and add their maps
      if (create_adc_ctrl_aon) begin
        adc_ctrl_aon =
            adc_ctrl_reg_block::type_id::create("adc_ctrl_aon");
        adc_ctrl_aon.set_ip_name("adc_ctrl_aon");
        adc_ctrl_aon.configure(.parent(this));
        adc_ctrl_aon.build(.base_addr(base_addr + 32'h40440000), .csr_excl(csr_excl));
        adc_ctrl_aon.set_hdl_path_root("tb.dut.top_earlgrey.u_adc_ctrl_aon",
                                       "BkdrRegPathRtl");
        adc_ctrl_aon.set_hdl_path_root("tb.dut.top_earlgrey.u_adc_ctrl_aon",
                                       "BkdrRegPathRtlCommitted");
        adc_ctrl_aon.set_hdl_path_root("tb.dut.top_earlgrey.u_adc_ctrl_aon",
                                       "BkdrRegPathRtlShadow");
        default_map.add_submap(.child_map(adc_ctrl_aon.default_map),
                               .offset(base_addr + 32'h40440000));
      end
      if (create_aes) begin
        aes =
